import { test, expect } from '@playwright/test';

/**
 * E2E tests for the S04 UI architecture:
 * - Toolbar restructuring (essential buttons only, no layer checkboxes in toolbar)
 * - View menu dropdown (open/close, layer toggles, grid visibility)
 * - Preferences modal (theme, units, grid, colors)
 * - Unit switching and persistence
 * - Grid visibility vs grid snap separation
 * - Settings persistence across reload
 */

test.describe('UI Architecture — Toolbar Structure', () => {
  test.beforeEach(async ({ page }) => {
    // Clear settings to start fresh
    await page.addInitScript(() => localStorage.removeItem('cypcb-settings'));
    await page.goto('/');
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
  });

  test('essential toolbar buttons are visible', async ({ page }) => {
    await expect(page.locator('#editor-toggle')).toBeVisible();
    await expect(page.locator('#undo-btn')).toBeVisible();
    await expect(page.locator('#redo-btn')).toBeVisible();
    await expect(page.locator('#fit-btn')).toBeVisible();
    await expect(page.locator('#view-menu-btn')).toBeVisible();
    await expect(page.locator('#view-3d-btn')).toBeVisible();
    await expect(page.locator('#theme-toggle')).toBeVisible();
    await expect(page.locator('#prefs-btn')).toBeVisible();
    await expect(page.locator('#open-btn')).toBeVisible();
  });

  test('layer checkboxes are NOT directly visible in toolbar (hidden in View dropdown)', async ({ page }) => {
    // The dropdown should be hidden by default
    await expect(page.locator('#view-menu-dropdown')).toHaveClass(/hidden/);
    // Layer checkboxes exist but are not visible (inside hidden dropdown)
    await expect(page.locator('#layer-top')).not.toBeVisible();
    await expect(page.locator('#layer-bottom')).not.toBeVisible();
    await expect(page.locator('#layer-ratsnest')).not.toBeVisible();
  });
});

test.describe('UI Architecture — View Menu', () => {
  test.beforeEach(async ({ page }) => {
    await page.addInitScript(() => localStorage.removeItem('cypcb-settings'));
    await page.goto('/');
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
  });

  test('View menu opens on click and closes on second click', async ({ page }) => {
    const dropdown = page.locator('#view-menu-dropdown');
    await expect(dropdown).toHaveClass(/hidden/);

    // Open
    await page.click('#view-menu-btn');
    await expect(dropdown).not.toHaveClass(/hidden/);

    // Close by clicking button again
    await page.click('#view-menu-btn');
    await expect(dropdown).toHaveClass(/hidden/);
  });

  test('View menu closes on Escape', async ({ page }) => {
    const dropdown = page.locator('#view-menu-dropdown');

    await page.click('#view-menu-btn');
    await expect(dropdown).not.toHaveClass(/hidden/);

    await page.keyboard.press('Escape');
    await expect(dropdown).toHaveClass(/hidden/);
  });

  test('View menu closes on click outside', async ({ page }) => {
    const dropdown = page.locator('#view-menu-dropdown');

    await page.click('#view-menu-btn');
    await expect(dropdown).not.toHaveClass(/hidden/);

    // Click somewhere else (the canvas)
    await page.click('#pcb-canvas');
    await expect(dropdown).toHaveClass(/hidden/);
  });

  test('layer toggle via View menu changes checkbox state', async ({ page }) => {
    // Open View menu
    await page.click('#view-menu-btn');
    await expect(page.locator('#view-menu-dropdown')).not.toHaveClass(/hidden/);

    const topCb = page.locator('#layer-top');
    await expect(topCb).toBeChecked();

    // Uncheck top layer
    await topCb.uncheck();
    await expect(topCb).not.toBeChecked();

    // Re-check
    await topCb.check();
    await expect(topCb).toBeChecked();
  });

  test('grid visibility toggle in View menu', async ({ page }) => {
    await page.click('#view-menu-btn');
    const gridCb = page.locator('#view-grid-visible');
    await expect(gridCb).toBeChecked();

    // Toggle off
    await gridCb.uncheck();
    await expect(gridCb).not.toBeChecked();

    // Verify setting was persisted
    const gridVisible = await page.evaluate(() => (window as any).__settings?.gridVisible);
    expect(gridVisible).toBe(false);

    // Toggle back on
    await gridCb.check();
    await expect(gridCb).toBeChecked();
    const gridVisibleAfter = await page.evaluate(() => (window as any).__settings?.gridVisible);
    expect(gridVisibleAfter).toBe(true);
  });
});

test.describe('UI Architecture — Preferences Modal', () => {
  test.beforeEach(async ({ page }) => {
    await page.addInitScript(() => localStorage.removeItem('cypcb-settings'));
    await page.goto('/');
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
  });

  test('Preferences modal opens and closes', async ({ page }) => {
    const overlay = page.locator('#prefs-overlay');
    await expect(overlay).toHaveClass(/hidden/);

    // Open
    await page.click('#prefs-btn');
    await expect(overlay).not.toHaveClass(/hidden/);

    // Close via X button
    await page.click('#prefs-close');
    await expect(overlay).toHaveClass(/hidden/);
  });

  test('Preferences modal closes on Escape', async ({ page }) => {
    const overlay = page.locator('#prefs-overlay');

    await page.click('#prefs-btn');
    await expect(overlay).not.toHaveClass(/hidden/);

    await page.keyboard.press('Escape');
    await expect(overlay).toHaveClass(/hidden/);
  });

  test('Preferences modal closes on backdrop click', async ({ page }) => {
    const overlay = page.locator('#prefs-overlay');

    await page.click('#prefs-btn');
    await expect(overlay).not.toHaveClass(/hidden/);

    // Click the overlay (backdrop), not the modal itself
    // The overlay fills the screen; click a corner far from the centered modal
    await page.click('#prefs-overlay', { position: { x: 5, y: 5 } });
    await expect(overlay).toHaveClass(/hidden/);
  });

  test('unit switching to mil updates coords display', async ({ page }) => {
    // Open Preferences
    await page.click('#prefs-btn');
    await expect(page.locator('#prefs-overlay')).not.toHaveClass(/hidden/);

    // Switch units to mil
    await page.selectOption('#prefs-units', 'mil');

    // Close modal
    await page.click('#prefs-close');

    // Move mouse over canvas to trigger coords update
    const canvas = page.locator('#pcb-canvas');
    const box = await canvas.boundingBox();
    if (box) {
      await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
    }

    // Wait for coords to update
    await page.waitForTimeout(200);

    // Verify units setting was applied
    const settings = await page.evaluate(() => (window as any).__settings);
    expect(settings.units).toBe('mil');
  });

  test('layer color change persists in settings', async ({ page }) => {
    await page.click('#prefs-btn');
    await expect(page.locator('#prefs-overlay')).not.toHaveClass(/hidden/);

    // Change top copper color
    const colorInput = page.locator('#prefs-color-top');
    await colorInput.fill('#00ff00');
    // Trigger change event (fill alone doesn't fire change on color inputs)
    await colorInput.dispatchEvent('change');

    // Verify setting persisted
    const settings = await page.evaluate(() => (window as any).__settings);
    expect(settings.layerColors.topCopper).toBe('#00ff00');
  });
});

test.describe('UI Architecture — Persistence', () => {
  test('unit setting persists across reload', async ({ page }) => {
    await page.goto('/');
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
    // Clear settings via evaluate (not addInitScript which re-runs on reload)
    await page.evaluate(() => localStorage.removeItem('cypcb-settings'));
    await page.reload();
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });

    // Open Preferences, switch to mil
    await page.click('#prefs-btn');
    await page.selectOption('#prefs-units', 'mil');
    await page.click('#prefs-close');

    // Verify it's set
    const unitsBefore = await page.evaluate(() => (window as any).__settings?.units);
    expect(unitsBefore).toBe('mil');

    // Reload page (no addInitScript to interfere)
    await page.reload();
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });

    // Verify unit persisted
    const unitsAfter = await page.evaluate(() => (window as any).__settings?.units);
    expect(unitsAfter).toBe('mil');
  });

  test('layer color persists across reload', async ({ page }) => {
    await page.goto('/');
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
    await page.evaluate(() => localStorage.removeItem('cypcb-settings'));
    await page.reload();
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });

    // Change top copper color via Preferences
    await page.click('#prefs-btn');
    const colorInput = page.locator('#prefs-color-top');
    await colorInput.fill('#abcdef');
    await colorInput.dispatchEvent('change');
    await page.click('#prefs-close');

    // Reload (settings should survive)
    await page.reload();
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });

    // Verify color persisted
    const settings = await page.evaluate(() => (window as any).__settings);
    expect(settings.layerColors.topCopper).toBe('#abcdef');
  });

  test('grid visibility vs grid snap are independent', async ({ page }) => {
    await page.addInitScript(() => localStorage.removeItem('cypcb-settings'));
    await page.goto('/');
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });

    // Toggle grid visibility off via View menu
    await page.click('#view-menu-btn');
    await page.locator('#view-grid-visible').uncheck();
    await page.click('#view-menu-btn'); // close menu

    // Read settings — gridVisible should be false, gridSnapSpacing unchanged
    const s1 = await page.evaluate(() => (window as any).__settings);
    expect(s1.gridVisible).toBe(false);
    expect(s1.gridSnapSpacing).toBe(1_270_000); // default 50mil

    // Now change grid snap via Preferences
    await page.click('#prefs-btn');
    const snapInput = page.locator('#prefs-grid-snap');
    await snapInput.fill('100mil');
    await snapInput.dispatchEvent('change');
    await page.click('#prefs-close');

    // Grid visibility should still be false, snap spacing changed
    const s2 = await page.evaluate(() => (window as any).__settings);
    expect(s2.gridVisible).toBe(false);
    expect(s2.gridSnapSpacing).toBe(2_540_000); // 100mil

    // Toggle grid visibility back on — snap spacing shouldn't change
    await page.click('#view-menu-btn');
    await page.locator('#view-grid-visible').check();
    await page.click('#view-menu-btn');

    const s3 = await page.evaluate(() => (window as any).__settings);
    expect(s3.gridVisible).toBe(true);
    expect(s3.gridSnapSpacing).toBe(2_540_000); // still 100mil
  });
});

import { test, expect } from '@playwright/test';

test.describe('App Load & WASM Initialization', () => {
  test('page loads with correct title', async ({ page }) => {
    await page.goto('/');
    await expect(page).toHaveTitle('CodeYourPCB Viewer');
  });

  test('WASM initializes and reaches Ready state', async ({ page }) => {
    await page.goto('/');
    const status = page.locator('#status-text');
    // WASM loads async — wait for Ready text
    await expect(status).toContainText('Ready', { timeout: 15_000 });
  });

  test('status bar is visible', async ({ page }) => {
    await page.goto('/');
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
    await expect(page.locator('#status')).toBeVisible();
  });

  test('PCB canvas element exists and is visible', async ({ page }) => {
    await page.goto('/');
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
    const canvas = page.locator('#pcb-canvas');
    await expect(canvas).toBeVisible();
    // Canvas should have non-zero dimensions
    const box = await canvas.boundingBox();
    expect(box).toBeTruthy();
    expect(box!.width).toBeGreaterThan(100);
    expect(box!.height).toBeGreaterThan(100);
  });

  test('toolbar elements are present', async ({ page }) => {
    await page.goto('/');
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
    await expect(page.locator('#editor-toggle')).toBeVisible();
    await expect(page.locator('#fit-btn')).toBeVisible();
    await expect(page.locator('#view-menu-btn')).toBeVisible();
    await expect(page.locator('#view-3d-btn')).toBeVisible();
    await expect(page.locator('#theme-toggle')).toBeVisible();
    await expect(page.locator('#prefs-btn')).toBeVisible();
    await expect(page.locator('#open-btn')).toBeVisible();
    // Layer checkboxes are inside View dropdown, not directly in toolbar
    await expect(page.locator('#view-menu-dropdown')).toHaveClass(/hidden/);
  });

  test('baseline screenshot of initial state', async ({ page }) => {
    await page.goto('/');
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
    await page.screenshot({ path: 'test-results/baseline-initial-state.png', fullPage: true });
  });
});

/**
 * Project Manager — startup screen with templates, recent files, and file open.
 *
 * Shows an overlay on app launch letting the user pick a template, open a recent
 * file, or import a .cypcb from disk. Dismissed automatically when a file loads.
 *
 * Debug surface: `window.__projectManager` exposes state for E2E tests.
 */

import { getPreference, setPreference, type RecentFileEntry } from './settings';
import { render, type RenderState } from './renderer';
import { createViewport, fitBoard } from './viewport';
import { createDefaultRenderConfig, buildPadNetMap } from './render-config';
import { createLayerVisibility } from './layers';
import type { BoardSnapshot } from './types';

// ---------------------------------------------------------------------------
// Template descriptors (static, bundled in public/templates/)
// ---------------------------------------------------------------------------

interface TemplateInfo {
  id: string;
  name: string;
  description: string;
  file: string;
}

const TEMPLATES: TemplateInfo[] = [
  {
    id: 'blink',
    name: 'Blink LED',
    description: '555 timer astable circuit — LED blinks at ~1.4 Hz',
    file: 'blink.cypcb',
  },
  {
    id: 'power-indicator',
    name: 'Power Indicator',
    description: 'Simple LED power indicator with current-limiting resistor',
    file: 'power-indicator.cypcb',
  },
  {
    id: 'simple-psu',
    name: 'Simple PSU',
    description: '5V regulated power supply — 7805 with filter caps',
    file: 'simple-psu.cypcb',
  },
];

// ---------------------------------------------------------------------------
// Blank project scaffold
// ---------------------------------------------------------------------------

const BLANK_SCAFFOLD = `version 1

board untitled {
    size 50mm x 50mm
    layers 2
}
`;

// ---------------------------------------------------------------------------
// Callbacks from the host (main.ts)
// ---------------------------------------------------------------------------

export interface ProjectManagerCallbacks {
  onOpenFile: () => void;
  onLoadTemplate: (source: string, name: string) => void;
  onNewBlank: (source: string) => void;
}

// ---------------------------------------------------------------------------
// Module state
// ---------------------------------------------------------------------------

let overlay: HTMLElement | null = null;
let recentListEl: HTMLElement | null = null;
let callbacks: ProjectManagerCallbacks | null = null;
let visible = false;

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Wire DOM event handlers on the project manager overlay.
 * Call once after WASM init.
 */
export function initProjectManager(cb: ProjectManagerCallbacks): void {
  callbacks = cb;

  overlay = document.getElementById('project-manager');
  recentListEl = document.getElementById('pm-recent-list');

  if (!overlay) {
    console.warn('[ProjectManager] #project-manager element not found');
    return;
  }

  // Template card clicks
  const templateCards = overlay.querySelectorAll<HTMLElement>('[data-template]');
  templateCards.forEach((card) => {
    card.addEventListener('click', () => {
      const templateId = card.dataset.template!;
      handleTemplateClick(templateId);
    });
  });

  // Blank card
  const blankCard = overlay.querySelector<HTMLElement>('[data-template-blank]');
  if (blankCard) {
    blankCard.addEventListener('click', () => {
      callbacks?.onNewBlank(BLANK_SCAFFOLD);
    });
  }

  // Open file button
  const openBtn = overlay.querySelector<HTMLElement>('#pm-open-btn');
  if (openBtn) {
    openBtn.addEventListener('click', () => {
      callbacks?.onOpenFile();
    });
  }

  exposeDebugSurface();
}

/**
 * Show the project manager overlay and populate dynamic content.
 */
export function showProjectManager(): void {
  if (!overlay) return;

  populateRecentFiles();
  overlay.classList.remove('hidden');
  visible = true;
  exposeDebugSurface();
}

/**
 * Hide the project manager overlay.
 */
export function hideProjectManager(): void {
  if (!overlay) return;

  overlay.classList.add('hidden');
  visible = false;
  exposeDebugSurface();
}

/**
 * Record a file open in the recent files list.
 * Generates a thumbnail from the current board state if a snapshot and canvas
 * context are available.
 *
 * @param name     Display name (filename)
 * @param snapshot Current board snapshot (optional, for thumbnail)
 * @param renderState Partial render state for thumbnail generation (optional)
 */
export function addRecentFile(
  name: string,
  snapshot?: BoardSnapshot | null,
  renderState?: Partial<RenderState> | null,
): void {
  const recentFiles = getPreference('recentFiles');

  // Remove existing entry with same name
  const filtered = recentFiles.filter((e) => e.name !== name);

  let thumbnail: string | null = null;
  if (snapshot && renderState) {
    try {
      thumbnail = generateThumbnail(snapshot, renderState);
    } catch (e) {
      console.warn('[ProjectManager] Thumbnail generation failed, using placeholder', e);
    }
  }

  const entry: RecentFileEntry = {
    name,
    timestamp: Date.now(),
    thumbnail,
  };

  filtered.unshift(entry);

  // Cap at 10 entries
  const capped = filtered.slice(0, 10);

  setPreference('recentFiles', capped);
  exposeDebugSurface();
}

/**
 * Generate a 200×150 thumbnail of the board via offscreen canvas.
 */
export function generateThumbnail(
  snapshot: BoardSnapshot,
  partialState: Partial<RenderState>,
): string {
  const width = 200;
  const height = 150;

  const offscreen = document.createElement('canvas');
  offscreen.width = width;
  offscreen.height = height;
  const ctx = offscreen.getContext('2d')!;

  // Build a minimal viewport fitted to the board
  let vp = createViewport(width, height);
  if (snapshot.board) {
    vp = fitBoard(vp, snapshot.board.width_nm, snapshot.board.height_nm, 10);
  }

  const layers = createLayerVisibility();
  const renderConfig = createDefaultRenderConfig();
  const padNetMap = snapshot.nets ? buildPadNetMap(snapshot.nets) : new Map<string, string>();

  const base: RenderState = {
    snapshot,
    viewport: vp,
    layers,
    selectedRefdes: null,
    showViolations: false,
    showRatsnest: false,
    colorByNet: true,
    selectedTraceId: null,
    hoveredTraceId: null,
    labelPosition: null,
    routing: null,
    highlightedNet: null,
    activeResizeHandle: null,
    renderConfig,
    padNetMap,
    gridVisible: false,
    gridVisualSpacing: 1_000_000,
    showNetLabels: false,
  };

  // Apply partial overrides but force our thumbnail viewport
  const state: RenderState = {
    ...base,
    ...partialState,
    snapshot,
    viewport: vp,
  };

  render(ctx, state);

  return offscreen.toDataURL('image/png');
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

async function handleTemplateClick(templateId: string): Promise<void> {
  const template = TEMPLATES.find((t) => t.id === templateId);
  if (!template || !callbacks) return;

  try {
    const resp = await fetch(`/templates/${template.file}`);
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const source = await resp.text();
    callbacks.onLoadTemplate(source, template.name);
  } catch (e) {
    console.error(`[ProjectManager] Failed to load template ${template.file}:`, e);
  }
}

function populateRecentFiles(): void {
  if (!recentListEl) return;

  const recentFiles = getPreference('recentFiles');

  // Clear existing content
  recentListEl.textContent = '';

  if (recentFiles.length === 0) {
    const empty = document.createElement('div');
    empty.className = 'pm-recent-empty';
    empty.textContent = 'No recent files';
    recentListEl.appendChild(empty);
    return;
  }

  recentFiles.forEach((entry) => {
    const item = document.createElement('div');
    item.className = 'pm-recent-item';
    item.addEventListener('click', () => {
      // Recent files just show info — we can't reopen them without File System Access
      // handles (which don't persist across sessions). For now, show the name.
      // In a real implementation with a backend, this would re-open the file.
      console.log(`[ProjectManager] Recent file clicked: ${entry.name}`);
    });

    if (entry.thumbnail) {
      const thumb = document.createElement('img');
      thumb.className = 'pm-recent-thumb';
      thumb.src = entry.thumbnail;
      thumb.alt = entry.name;
      thumb.width = 48;
      thumb.height = 36;
      item.appendChild(thumb);
    } else {
      const placeholder = document.createElement('div');
      placeholder.className = 'pm-recent-thumb-placeholder';
      placeholder.textContent = '📄';
      item.appendChild(placeholder);
    }

    const info = document.createElement('div');
    info.className = 'pm-recent-info';

    const nameEl = document.createElement('div');
    nameEl.className = 'pm-recent-name';
    nameEl.textContent = entry.name;
    info.appendChild(nameEl);

    const dateEl = document.createElement('div');
    dateEl.className = 'pm-recent-date';
    dateEl.textContent = formatRelativeDate(entry.timestamp);
    info.appendChild(dateEl);

    item.appendChild(info);
    recentListEl!.appendChild(item);
  });
}

function formatRelativeDate(ts: number): string {
  const diff = Date.now() - ts;
  const minutes = Math.floor(diff / 60_000);
  if (minutes < 1) return 'Just now';
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${days}d ago`;
  return new Date(ts).toLocaleDateString();
}

// ---------------------------------------------------------------------------
// Debug surface
// ---------------------------------------------------------------------------

function exposeDebugSurface(): void {
  if (typeof window === 'undefined') return;

  (window as any).__projectManager = {
    get visible() { return visible; },
    get recentFiles() { return getPreference('recentFiles'); },
    get templateCount() { return TEMPLATES.length; },
  };
}
